    "Go to Aloha Social app" : "Joan Aloha Social aplikaziora",
    "_One account could not be reached from this server:_::_%n accounts could not be reached from this server:_" : ["Kontu bat ezin izan da iritsi zerbitzari honetatik:","%n kontu ezin izan dira iritsi zerbitzari honetatik:"],
    "Add some with the starter_packs app setting, or read them in from other servers with starter_pack_sources." : "Gehitu batzuk starter_packs aplikazio-ezarpenarekin, edo irakurri beste zerbitzarietatik starter_pack_sources bidez.",
    "This server does not suggest any starter packs yet." : "Zerbitzari honek ez du oraindik hasierako paketerik iradokitzen.",
    "Videos people are watching will appear here." : "Jendea ikusten ari den bideoak hemen agertuko dira.",
